 public function retryTask(int$id,int$u,int$lock):array{return$this->tx(function()use($id,$u,$lock){$t=$this->tasks->lockOwnedForRetry($id,$u)??throw new TaskNotFoundException('not_found');if((int)$t['lock_version']!==$lock)throw new TaskConcurrencyException('concurrency_conflict');if($t['status']!=='failed')throw new TaskTransitionException('retry_task_invalid');$this->machine->assertTransition('failed','ready');if((int)$t['attempt_count']>=(int)$t['max_attempts'])throw new TaskTransitionException('attempt_limit');$stepId=(int)($t['current_step_id_']??0);if($stepId<1)throw new TaskTransitionException('retry_step_invalid');$step=$this->steps->lockForRetry($stepId,$id)??throw new TaskTransitionException('retry_step_invalid');if($step['status']!=='failed')throw new TaskTransitionException('retry_step_invalid');$this->stepMachine->assertTransition('failed','ready');$this->steps->updateStatus($stepId,'ready',(int)$step['lock_version'],['error_message'=>null]);$n=$this->tasks->retry($id,$u,$lock);$this->events->append(['task_id'=>$id,'step_id'=>$stepId,'actor_type'=>'user','actor_user_id'=>$u,'event_key'=>'task_ready','from_status'=>'failed','to_status'=>'ready','summary'=>'Tarea preparada para reintento.','details'=>['attempt_count'=>(int)$n['attempt_count']]]);return$n;});}
 public function prepareChatTurn(int$u,int$session,?int$project,int$message,string$key,string$title,string$objective,bool$auto,array$input=[]):ChatTaskContext{return$this->tx(function()use($u,$session,$project,$message,$key,$title,$objective,$auto,$input){$task=$this->tasks->findOwnedByIdempotencyKey($u,$key);if(!$task){$task=$this->tasks->create(['public_id'=>TaskPublicId::generate(),'user_id'=>$u,'created_by_user_id'=>$u,'project_id'=>$project,'session_id'=>$session,'origin_message_id'=>$message,'idempotency_key'=>$key,'origin_type'=>'chat','title'=>$title,'objective'=>$objective,'status'=>'pending','priority'=>'normal','max_attempts'=>1]);$this->event((int)$task['id_'],'task_created',null,'pending','Tarea de chat creada.',$u);}$step=$this->steps->findByKey((int)$task['id_'],'respond');if(!$step){$input['execution_mode']=($input['execution_mode']??'sync')==='async'?'async':'sync';$step=$this->steps->createRespond((int)$task['id_'],$input);$this->event((int)$task['id_'],'step_created',null,'pending','Step respond creado.',$u,(int)$step['id_']);}
 $target=$auto?'ready':'waiting_user';if($task['status']==='pending'){$this->machine->assertTransition('pending',$target);$task=$this->tasks->updateStatus((int)$task['id_'],$u,$target,(int)$task['lock_version']);$this->event((int)$task['id_'],'task_'.$target,'pending',$target,$auto?'Tarea lista.':'Esperando aprobación humana.',$u);}if($step['status']==='pending'){$this->stepMachine->assertTransition('pending',$target);$step=$this->steps->updateStatus((int)$step['id_'],$target,(int)$step['lock_version']);$this->event((int)$task['id_'],'step_'.$target,'pending',$target,$auto?'Step listo.':'Esperando aprobación humana.',$u,(int)$step['id_']);if(!$auto)$this->event((int)$task['id_'],'approval_requested',null,'waiting_user','Aprobación de inicio solicitada.',$u,(int)$step['id_']);}
 return new ChatTaskContext((int)$task['id_'],(string)$task['public_id'],(int)$step['id_'],null,null,(int)$task['lock_version'],(int)$step['lock_version']);});}
 public function beginApprovedChatExecution(string$public,int$u,string$trace,string$model):ChatTaskContext{$task=$this->tasks->findOwnedByPublicId($public,$u)??throw new TaskNotFoundException('not_found');$step=$this->steps->findByKey((int)$task['id_'],'respond')??throw new TaskNotFoundException('step_not_found');return$this->beginChatExecution(new ChatTaskContext((int)$task['id_'],$public,(int)$step['id_'],null,null,(int)$task['lock_version'],(int)$step['lock_version']),$u,$trace,$model);}
 public function beginChatExecution(ChatTaskContext$c,int$u,string$trace,string$model):ChatTaskContext{return$this->tx(function()use($c,$u,$trace,$model){$task=$this->tasks->findOwnedById($c->taskId,$u)??throw new TaskNotFoundException('not_found');$step=$this->steps->findById($c->stepId)??throw new TaskNotFoundException('step_not_found');if($task['status']!=='ready'||$step['status']!=='ready')throw new TaskTransitionException('task_not_ready');$existing=$this->executions->findAttempt((int)$step['id_'],1);if($existing)throw new TaskConcurrencyException('execution_already_started');$execution=$this->executions->create((int)$task['id_'],(int)$step['id_'],$trace,$model);$this->event((int)$task['id_'],'execution_created',null,'queued','Ejecución creada.',$u,(int)$step['id_'],(int)$execution['id_']);$task=$this->tasks->updateStatus((int)$task['id_'],$u,'running',(int)$task['lock_version']);$step=$this->steps->updateStatus((int)$step['id_'],'running',(int)$step['lock_version']);$this->executionMachine->assertTransition('queued','running');$execution=$this->executions->updateStatus((int)$execution['id_'],'running',null,$model);$this->event((int)$task['id_'],'execution_started','queued','running','Ejecución iniciada.',$u,(int)$step['id_'],(int)$execution['id_']);return new ChatTaskContext((int)$task['id_'],(string)$task['public_id'],(int)$step['id_'],(int)$execution['id_'],$trace,(int)$task['lock_version'],(int)$step['lock_version']);});}
 public function approveChatTask(int$id,int$u,int$lock):array{return$this->decideChatTask($id,$u,$lock,true);}
